+    await typeSecret('s3cr3t-TOKEN-42');
     harness.sendEnter(); // grant #1 -> mock turn 2 requests another secret
     await harness.waitForText(
       'OTHER_API_KEY',
@@ -115,9 +171,8 @@ void main() {
     );
