/// not landed in this frame yet). Top-level (like [frameContentLines])
/// so the row-anchor rule is unit-testable without a PTY.
String? maskedValueRow(String screen) => screen
    .split('\n')
    .where((l) => l.contains('•') && l.trimRight().endsWith('│'))
