test(
  'every bullet-run screen anchor that feeds frame-closed row reads '
  're-anchors once (gh-1244 review thread / gh-1257)',
  () {
    // The gh-1244 review thread fixed a real race with typeSecret's
    // one-shot re-anchor: the anchored frame can predate the value
    // row's closing `│` border by one repaint, and a row-dependent
    // read through the frame-closed guard (maskedValueRow / the
    // `│`-closed row filter) then either throws (null row) or
    // silently sees a partial row set — a new flake in the very
    // suite the anchor de-flakes. Any `screen = waitForScreen('•' * …)`
    // anchor in the PTY secret lanes must therefore be followed by
    // the re-anchor
    //   if (<frame-closed guard>) {
    //     screen = await harness.waitForScreen(<same marker>, ...);
    //   }
    // before the next settle/keystroke. Hermetic source scan (no PTY,
    // no network), same default-suite discipline as the gh-1049 guard.
    const laneFiles = [
      'test/integration/secret_sheet_residual_test.dart',
      'test/integration/password_prompt_pty_test.dart',
    ];
    final violations = <String>[];
    for (final path in laneFiles) {
      final lines = _codeLines(File(path).readAsLinesSync());
      for (var i = 0; i < lines.length; i++) {
        final line = lines[i];
        // The INITIAL anchor assigns with `var`/`final`; the re-anchor
        // reassigns bare `screen =` inside the guard, so the two never
        // collide. The `'•' *` marker may sit on the next line.
        final isInitialAnchor = RegExp(
          r'\b(?:var|final)\s+screen\s*=\s*await\s+[\w.]*waitForScreen\(',
        ).hasMatch(line);
        if (!isInitialAnchor) continue;
        final end = _statementEnd(lines, i);
        final isBulletAnchor = lines
            .sublist(i, end + 1)
            .any((l) => l.contains("'•' *"));
        if (!isBulletAnchor) continue;
        var reanchored = false;
        for (var j = i + 1; j <= end + 12 && j < lines.length; j++) {
          final l = lines[j];
          // The re-anchor reassignment itself mentions waitForScreen —
          // test it BEFORE the window-enders break below.
          if (RegExp(
            r'\bscreen\s*=\s*await\s+[\w.]*waitForScreen\(',
          ).hasMatch(l)) {
            reanchored = true;
            break;
          }
          if (_windowEnders.any(l.contains)) break;
          if (l.contains('sendEnter()') || l.contains('sendEscape()')) {
            break;
          }
        }
        if (!reanchored) {
          violations.add(
            '$path:${i + 1}: bullet-run anchor assigns `screen` but no '
            'one-shot re-anchor follows before the next settle/keystroke '
            '— a frame predating the value row\'s closing `│` border '
            'fails the frame-closed row read (gh-1244 review thread, '
            'gh-1257).',
          );
        }
      }
    }
    expect(violations, isEmpty, reason: violations.join('\n'));
  },
);

