      // no network), same default-suite discipline as the gh-1049 guard.
      const laneFiles = [
        'test/integration/secret_sheet_residual_test.dart',
        'test/integration/password_prompt_pty_test.dart',
      ];
      final violations = <String>[];
      for (final path in laneFiles) {
        final lines = _codeLines(File(path).readAsLinesSync());
        for (var i = 0; i < lines.length; i++) {
          final line = lines[i];
