          // reassigns bare `screen =` inside the guard, so the two never
          // collide. The `'•' *` marker may sit on the next line.
          final isInitialAnchor = RegExp(
            r'\b(?:var|final)\s+screen\s*=\s*await\s+[\w.]*waitForScreen\(',
          ).hasMatch(line);
          if (!isInitialAnchor) continue;
          final end = _statementEnd(lines, i);
          final isBulletAnchor = lines
              .sublist(i, end + 1)
              .any((l) => l.contains("'•' *"));
          if (!isBulletAnchor) continue;
          var reanchored = false;
          for (var j = i + 1; j <= end + 12 && j < lines.length; j++) {
            final l = lines[j];
            // The re-anchor reassignment itself mentions waitForScreen —
            // test it BEFORE the window-enders break below.
            if (RegExp(
              r'\bscreen\s*=\s*await\s+[\w.]*waitForScreen\(',
            ).hasMatch(l)) {
              reanchored = true;
