/// Bullet counts of ALL frame-closed masked rows on a captured screen —
/// `maskedValueRow`'s `│` guard generalized from the first row to every
/// row. RT4's multiline value renders ONE FRAME ROW PER LINE, so the
/// shape pin needs all of them; a single-row read can never see every
/// pasted bullet.
List<int> frameClosedBulletCounts(String screen) => screen
    .split('\n')
    .where((l) => l.contains('•') && l.trimRight().endsWith('│'))
    .map((l) => l.split('•').length - 1)
    .toList();

