  'waitForScreen(',
  'waitForText(',
  'waitForOutput(',
  'waitForBoot(',
];

/// The primitive itself: its internal `screenText` polls ARE the wait.
const _excluded = {
  'pty_harness.dart',
  // This file's own scan literals would trip the naive matcher.
  'pty_screen_wait_reg_test.dart',
};

void main() {
